import 'dart:convert';
import 'package:http/http.dart' as http;
class AurenTvChannel { final String id,name,logo,country,language,category,url; const AurenTvChannel({required this.id,required this.name,required this.logo,required this.country,required this.language,required this.category,required this.url}); }
class AurenTvService {
 AurenTvService._(); static final instance=AurenTvService._(); static const playlist='https://iptv-org.github.io/iptv/index.country.m3u'; List<AurenTvChannel>? _cache;
 Future<List<AurenTvChannel>> load({String country='',String category=''}) async { _cache ??= await _fetch(); final c=country.trim().toLowerCase(), k=category.trim().toLowerCase(); return _cache!.where((x)=>(c.isEmpty||x.country.toLowerCase()==c)&&(k.isEmpty||x.category.toLowerCase()==k)).take(300).toList(); }
 Future<List<AurenTvChannel>> _fetch() async { final r=await http.get(Uri.parse(playlist)).timeout(const Duration(seconds:20)); if(r.statusCode!=200) throw Exception('IPTV playlist unavailable'); final lines=const LineSplitter().convert(r.body); final out=<AurenTvChannel>[]; Map<String,String> meta={}; for(final line in lines){ if(line.startsWith('#EXTINF:')){meta={'name':_attr(line,'tvg-name')??line.split(',').last.trim(),'logo':_attr(line,'tvg-logo')??'','country':_attr(line,'tvg-country')??'','language':_attr(line,'tvg-language')??'','category':_attr(line,'group-title')??''};} else if(line.startsWith('http')&&meta.isNotEmpty){out.add(AurenTvChannel(id:'tv-'+out.length.toString(),name:meta['name']!,logo:meta['logo']!,country:meta['country']!,language:meta['language']!,category:meta['category']!,url:line.trim()));meta={};}} return out; }
 static String? _attr(String s,String key){final m=RegExp(key+'="([^"]*)"').firstMatch(s);return m?.group(1);}
}